// devViewer.js - development-only clip viewer.
//
// Only reachable with ?dev=viewer in the URL (main.js dynamic-imports this
// module and pauses the game loop). It shows the rigged Mixamo character, every
// mapped clip, and the mirrored variant generated by mirrorClip(). This is the
// tool used to validate direction and clip/state mappings visually.
import * as THREE from 'three';
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls.js';
import { clone as cloneSkeleton } from 'three/examples/jsm/utils/SkeletonUtils.js';
import { loadCharacterAssets, getClip, CLIP_DEFINITIONS, EXTRA_CLIP_FILES } from './assets.js';

const STYLE = `
#ddv-root{position:fixed;inset:0;background:#0b1020;color:#e8f0ff;font-family:"Segoe UI",Roboto,Arial,sans-serif;z-index:10000}
#ddv-root canvas{display:block;width:100%;height:100%}
#ddv-panel{position:absolute;top:14px;left:14px;width:320px;max-height:calc(100% - 28px);overflow:auto;padding:14px 16px;border-radius:14px;background:rgba(8,14,30,.88);border:1px solid rgba(255,255,255,.14);backdrop-filter:blur(8px);font-size:13px}
#ddv-panel h1{margin:0 0 2px;font-size:17px;letter-spacing:.06em}
#ddv-panel .ddv-sub{opacity:.6;font-size:11px;margin-bottom:12px}
#ddv-panel label{display:block;font-size:11px;letter-spacing:.14em;opacity:.7;margin:12px 0 5px}
#ddv-panel select,#ddv-panel input[type=range]{width:100%}
#ddv-panel select{padding:7px;border-radius:8px;background:#16203a;color:#fff;border:1px solid rgba(255,255,255,.2)}
#ddv-panel button{cursor:pointer;font:inherit;font-weight:700;padding:8px 12px;border-radius:8px;border:1px solid rgba(255,255,255,.2);background:#1b2947;color:#fff;margin:8px 6px 0 0}
#ddv-panel button.ddv-on{background:#ffd600;color:#201300;border-color:transparent}
#ddv-info{margin-top:12px;padding:9px 10px;border-radius:8px;background:rgba(255,255,255,.07);font-size:11px;line-height:1.55;white-space:pre-wrap}
#ddv-status{position:absolute;left:50%;top:18px;transform:translateX(-50%);padding:8px 14px;border-radius:999px;background:rgba(8,14,30,.9);border:1px solid rgba(255,255,255,.14);font-size:12px}
#ddv-hint{position:absolute;left:50%;bottom:14px;transform:translateX(-50%);font-size:11px;opacity:.55}
`;

function buildPanel() {
  const root = document.createElement('div');
  root.id = 'ddv-root';
  root.innerHTML = `
    <div id="ddv-panel">
      <h1>ANIMATION VIEWER</h1>
      <div class="ddv-sub">Mode développement · ?dev=viewer</div>
      <label for="ddv-select">CLIP</label>
      <select id="ddv-select"></select>
      <label>VITESSE <span id="ddv-speed-value">1.00×</span></label>
      <input id="ddv-speed" type="range" min="0" max="2.5" step="0.05" value="1">
      <label>TEMPS <span id="ddv-time-value">0.00s</span></label>
      <input id="ddv-time" type="range" min="0" max="1" step="0.001" value="0">
      <div>
        <button id="ddv-play" class="ddv-on">LECTURE</button>
        <button id="ddv-mirror">MIROIR</button>
        <button id="ddv-loop" class="ddv-on">BOUCLE</button>
        <button id="ddv-reset">CAMÉRA</button>
      </div>
      <div id="ddv-info">Chargement…</div>
    </div>
    <div id="ddv-status">Chargement des assets…</div>
    <div id="ddv-hint">Souris : orbite · molette : zoom · ← → : clip précédent/suivant · M : miroir · ESPACE : lecture</div>
  `;
  document.body.appendChild(root);
  return root;
}

export function startDevViewer() {
  const style = document.createElement('style');
  style.textContent = STYLE;
  document.head.appendChild(style);
  const root = buildPanel();

  const ui = {
    select: root.querySelector('#ddv-select'),
    speed: root.querySelector('#ddv-speed'),
    speedValue: root.querySelector('#ddv-speed-value'),
    time: root.querySelector('#ddv-time'),
    timeValue: root.querySelector('#ddv-time-value'),
    play: root.querySelector('#ddv-play'),
    mirror: root.querySelector('#ddv-mirror'),
    loop: root.querySelector('#ddv-loop'),
    reset: root.querySelector('#ddv-reset'),
    info: root.querySelector('#ddv-info'),
    status: root.querySelector('#ddv-status')
  };

  const scene = new THREE.Scene();
  scene.background = new THREE.Color(0x0b1020);
  scene.fog = new THREE.Fog(0x0b1020, 18, 42);

  const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 200);
  const defaultCamera = new THREE.Vector3(3.2, 2.1, 4.6);
  camera.position.copy(defaultCamera);

  const renderer = new THREE.WebGLRenderer({ antialias: true });
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
  renderer.shadowMap.enabled = true;
  renderer.shadowMap.type = THREE.PCFSoftShadowMap;
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  root.appendChild(renderer.domElement);

  const controls = new OrbitControls(camera, renderer.domElement);
  controls.target.set(0, 1, 0);
  controls.enableDamping = true;
  controls.dampingFactor = 0.08;
  controls.minDistance = 1.5;
  controls.maxDistance = 25;

  scene.add(new THREE.HemisphereLight(0xcfe6ff, 0x223311, 1.4));
  const key = new THREE.DirectionalLight(0xffffff, 2.6);
  key.position.set(4, 7, 5);
  key.castShadow = true;
  key.shadow.mapSize.set(1024, 1024);
  key.shadow.camera.left = -6;
  key.shadow.camera.right = 6;
  key.shadow.camera.top = 6;
  key.shadow.camera.bottom = -6;
  scene.add(key);
  const rim = new THREE.DirectionalLight(0x6fa8ff, 1.2);
  rim.position.set(-5, 4, -6);
  scene.add(rim);

  const ground = new THREE.Mesh(
    new THREE.CircleGeometry(7, 48),
    new THREE.MeshStandardMaterial({ color: 0x2b8a3a, roughness: 0.95 })
  );
  ground.rotation.x = -Math.PI / 2;
  ground.receiveShadow = true;
  scene.add(ground);
  const grid = new THREE.GridHelper(14, 28, 0x4a7a5a, 0x2f5a3d);
  grid.position.y = 0.002;
  scene.add(grid);

  const viewer = {
    assets: null,
    model: null,
    mixer: null,
    action: null,
    entries: [],
    index: 0,
    mirrored: false,
    playing: true,
    loop: true,
    speed: 1,
    duration: 1,
    scrubbing: false
  };

  function refreshEntries() {
    const names = Object.keys(CLIP_DEFINITIONS);
    viewer.entries = names.map((action) => {
      const definition = CLIP_DEFINITIONS[action];
      return {
        action,
        directional: Boolean(definition.directional),
        file: definition.file,
        pendingValidation: definition.pendingValidation || null
      };
    });
  }
  refreshEntries();

  function populateSelect() {
    ui.select.textContent = '';
    viewer.entries.forEach((entry, index) => {
      const option = document.createElement('option');
      option.value = String(index);
      option.textContent = entry.action + (entry.directional ? '  (directionnel)' : '');
      ui.select.appendChild(option);
    });
    // Extra clips are listed too, even if they are not mapped to a state.
    EXTRA_CLIP_FILES.forEach((file) => {
      const option = document.createElement('option');
      option.value = 'extra:' + file;
      option.disabled = true;
      option.textContent = 'extra · ' + file;
      ui.select.appendChild(option);
    });
  }
  populateSelect();

  function applyClip() {
    const entry = viewer.entries[viewer.index];
    if (!entry || !viewer.assets || !viewer.assets.ready) return;
    const clip = getClip(viewer.assets, entry.action, viewer.mirrored);
    if (!clip) {
      ui.info.textContent = 'Clip introuvable : ' + entry.action;
      return;
    }
    if (viewer.action) viewer.action.stop();
    viewer.action = viewer.mixer.clipAction(clip);
    viewer.action.reset();
    viewer.action.setLoop(viewer.loop ? THREE.LoopRepeat : THREE.LoopOnce, Infinity);
    viewer.action.clampWhenFinished = !viewer.loop;
    viewer.action.setEffectiveTimeScale(viewer.speed);
    viewer.action.enabled = true;
    viewer.action.setEffectiveWeight(1);
    viewer.action.play();
    viewer.duration = Math.max(0.001, clip.duration);
    viewer.action.time = 0;
    ui.time.value = '0';
    ui.select.value = String(viewer.index);
    ui.info.textContent = [
      'action      ' + entry.action,
      'fichier     ' + entry.file,
      'durée       ' + clip.duration.toFixed(3) + ' s',
      'pistes      ' + clip.tracks.length,
      'boucle      ' + (CLIP_DEFINITIONS[entry.action].once ? 'non (one-shot)' : 'oui'),
      'direction   ' + (entry.directional ? 'clip directionnel' : 'neutre'),
      'miroir      ' + (viewer.mirrored ? 'OUI' : 'non'),
      entry.pendingValidation ? 'À VALIDER   ' + entry.pendingValidation : ''
    ].filter(Boolean).join('\n');
    ui.mirror.classList.toggle('ddv-on', viewer.mirrored);
  }

  function selectIndex(index) {
    viewer.index = (index + viewer.entries.length) % viewer.entries.length;
    applyClip();
  }

  ui.select.addEventListener('change', () => selectIndex(Number(ui.select.value) || 0));
  ui.speed.addEventListener('input', () => {
    viewer.speed = Number(ui.speed.value);
    ui.speedValue.textContent = viewer.speed.toFixed(2) + '×';
    if (viewer.action) viewer.action.setEffectiveTimeScale(viewer.speed);
  });
  ui.play.addEventListener('click', () => {
    viewer.playing = !viewer.playing;
    ui.play.classList.toggle('ddv-on', viewer.playing);
    ui.play.textContent = viewer.playing ? 'LECTURE' : 'PAUSE';
  });
  ui.mirror.addEventListener('click', () => {
    viewer.mirrored = !viewer.mirrored;
    applyClip();
  });
  ui.loop.addEventListener('click', () => {
    viewer.loop = !viewer.loop;
    ui.loop.classList.toggle('ddv-on', viewer.loop);
    applyClip();
  });
  ui.reset.addEventListener('click', () => {
    camera.position.copy(defaultCamera);
    controls.target.set(0, 1, 0);
    controls.update();
  });
  ui.time.addEventListener('input', () => {
    viewer.scrubbing = true;
    if (viewer.action) {
      viewer.action.paused = true;
      viewer.action.time = Number(ui.time.value) * viewer.duration;
    }
  });
  ui.time.addEventListener('change', () => {
    viewer.scrubbing = false;
    if (viewer.action) viewer.action.paused = false;
  });

  window.addEventListener('keydown', (event) => {
    if (event.target && /INPUT|SELECT|TEXTAREA/.test(event.target.tagName)) return;
    if (event.key === 'ArrowRight') selectIndex(viewer.index + 1);
    if (event.key === 'ArrowLeft') selectIndex(viewer.index - 1);
    if (event.key.toLowerCase() === 'm') {
      viewer.mirrored = !viewer.mirrored;
      applyClip();
    }
    if (event.code === 'Space') {
      event.preventDefault();
      ui.play.click();
    }
  });

  window.addEventListener('resize', () => {
    camera.aspect = window.innerWidth / window.innerHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(window.innerWidth, window.innerHeight);
  });

  loadCharacterAssets((progress) => {
    ui.status.textContent = 'Chargement ' + progress.loaded + '/' + progress.total + ' · ' + progress.label;
  }).then((assets) => {
    viewer.assets = assets;
    if (!assets.ready) {
      ui.status.textContent = 'Assets manquants : ' + assets.missing.join(', ');
      return;
    }
    const model = cloneSkeleton(assets.prototype);
    model.scale.setScalar(assets.scale);
    model.position.y = assets.groundOffset;
    model.traverse((child) => {
      if (!child.isMesh) return;
      child.castShadow = true;
      child.frustumCulled = false;
      child.material = new THREE.MeshStandardMaterial({
        map: child.material && child.material.map ? child.material.map : null,
        color: 0xffffff, roughness: 0.7, metalness: 0.05
      });
    });
    scene.add(model);
    viewer.model = model;
    viewer.mixer = new THREE.AnimationMixer(model);
    viewer.mixer.timeScale = 1;
    ui.status.textContent = 'Prêt · ' + assets.clipInfo.length + ' clips · échelle ' + assets.scale.toFixed(3)
      + ' · taille ' + assets.heightCm + ' cm';
    applyClip();
  });

  const clock = new THREE.Clock();
  function animate() {
    requestAnimationFrame(animate);
    const delta = Math.min(clock.getDelta(), 0.05);
    if (viewer.mixer && viewer.playing && !viewer.scrubbing) viewer.mixer.update(delta);
    if (viewer.action) {
      const duration = viewer.duration;
      const time = viewer.loop ? viewer.action.time % duration : Math.min(viewer.action.time, duration);
      ui.time.value = String(time / duration);
      ui.timeValue.textContent = time.toFixed(2) + 's';
    }
    controls.update();
    renderer.render(scene, camera);
  }
  animate();

  window.__devViewer = viewer;
}
